    public static void main(String[] args) {
        int a = 5, b = 2;
        System.out.print(a / b + " " + a % b);
    }
}

#include <stdio.h>

int main() {
    int x = 8;
    int y = x << 2;
    int z = x >> 1;
    printf("%d", y + z);
    return 0;
}

abstract class Calc {
    abstract int add(int a, int b);
}

class MyCalc extends Calc {
    int add(int a, int b) {
        return a + b;
    }
}

public class Main {
    public static void main(String[] args) {
        Calc c = new MyCalc();
        System.out.print(c.add(15, 25));
    }
}

